-- Standalone rebuild only. Fail before any DDL if this is an existing application database.
do $$ begin if exists(select 1 from information_schema.tables where table_schema='public' and table_name in ('workspaces','profiles','orders','inventory','team_members')) then raise exception 'Golden rule: this migration requires a separate empty development database. Existing app detected.';end if;end $$;
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name))>0),created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null default '',display_name text not null default '',created_at timestamptz not null default now());
create table public.workspace_members(workspace_id uuid not null references public.workspaces(id),user_id uuid not null references auth.users(id),role text not null check(role in ('admin','manager','staff','viewer')),created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create function private.has_role(w uuid,roles text[] default array['admin','manager','staff','viewer']) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.workspace_members where workspace_id=w and user_id=auth.uid() and role=any(roles)) $$;
revoke all on function private.has_role(uuid,text[]) from public,anon;
grant execute on function private.has_role(uuid,text[]) to authenticated;
create function private.require_role(w uuid,roles text[]) returns void language plpgsql security definer set search_path='' as $$ begin if not private.has_role(w,roles) then raise exception 'Approved workspace access required' using errcode='42501'; end if; perform 1 from public.workspaces where id=w for update; end $$;
revoke all on function private.require_role(uuid,text[]) from public,anon,authenticated;
create function private.create_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,display_name) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing;return new;end $$;
revoke all on function private.create_profile() from public,anon,authenticated;
create trigger create_rebuild_profile after insert on auth.users for each row execute function private.create_profile();
create table public.vendors(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),name text not null check(length(trim(name))>0),contact_person text,email text,phone text,website text,lead_time_days integer,rating numeric,notes text,created_at timestamptz not null default now(),created_by uuid default auth.uid(),unique(workspace_id,id));
create table public.team_members(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),name text not null check(length(trim(name))>0),phone text,email text,base_reward numeric(14,2) not null default 5 check(base_reward>=0),reward_trigger text not null default 'delivered' check(reward_trigger in ('confirmed','delivered')),reward_calculation_mode text not null default 'per_order' check(reward_calculation_mode in ('per_order','per_item')),status text not null default 'active' check(status in ('active','inactive')),total_paid numeric(14,2) not null default 0 check(total_paid>=0),notes text,created_at timestamptz not null default now(),created_by uuid default auth.uid(),updated_at timestamptz not null default now(),unique(workspace_id,id));
create table public.inventory(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),title text not null check(length(trim(title))>0),sku text,category text not null default 'Other',condition text not null default 'new' check(condition in ('new','like_new','good','fair')),cost_price numeric(14,4) not null default 0 check(cost_price>=0),selling_price numeric(14,2) not null default 0 check(selling_price>=0),stock integer not null default 0 check(stock>=0),low_stock_threshold integer not null default 2 check(low_stock_threshold>=0),vendor_id uuid,vendor_name text,listing_url text,status text not null default 'active' check(status in ('active','sold','draft','out_of_stock','reserved','archived')),fulfillment_type text not null default 'both' check(fulfillment_type in ('local','shipping','both')),notes text,is_bundle boolean not null default false,bundle_items jsonb not null default '[]',batches jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid default auth.uid(),unique(workspace_id,id),foreign key(workspace_id,vendor_id) references public.vendors(workspace_id,id));
create table public.orders(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),item_id uuid,item_title text not null check(length(trim(item_title))>0),quantity integer not null check(quantity>0),unit_cost numeric(14,4) not null default 0 check(unit_cost>=0),sale_price numeric(14,2) not null check(sale_price>=0),shipping_charged numeric(14,2) not null default 0 check(shipping_charged>=0),shipping_cost numeric(14,2) not null default 0 check(shipping_cost>=0),platform_fee numeric(14,2) not null default 0 check(platform_fee>=0),total_revenue numeric(14,2) not null default 0,total_cost numeric(14,2) not null default 0,net_profit numeric(14,2) not null default 0,profit_margin numeric(12,4) not null default 0,buyer_name text not null default '',customer_phone text,customer_address text,google_maps_url text,payment_method text not null default 'cash' check(payment_method in ('fb_pay','cash','venmo','zelle','paypal','other')),fulfillment_type text not null default 'local_pickup' check(fulfillment_type in ('local_pickup','shipping')),carrier text,tracking_number text,status text not null default 'new' check(status in ('new','confirmed','delivered','cancelled','completed','pending_pickup','shipped')),date date not null default (now() at time zone 'Africa/Casablanca')::date,delivered_date date,notes text,created_at timestamptz not null default now(),created_by uuid default auth.uid(),confirmation_member_id uuid,confirmation_member_name text,base_price numeric(14,2),member_reward numeric(14,2) not null default 0 check(member_reward>=0),reward_trigger text check(reward_trigger in ('confirmed','delivered')),reward_status text not null default 'pending' check(reward_status in ('pending','granted','cancelled')),reward_calculation_mode text check(reward_calculation_mode in ('per_order','per_item')),stock_allocations jsonb not null default '[]',unique(workspace_id,id),foreign key(workspace_id,item_id) references public.inventory(workspace_id,id),foreign key(workspace_id,confirmation_member_id) references public.team_members(workspace_id,id));
create table public.team_payouts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),member_id uuid not null,member_name text not null,amount numeric(14,2) not null check(amount>0),date date not null default (now() at time zone 'Africa/Casablanca')::date,payment_method text not null default 'cash',notes text,created_at timestamptz not null default now(),created_by uuid default auth.uid(),foreign key(workspace_id,member_id) references public.team_members(workspace_id,id));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),product_id uuid not null,order_id uuid,quantity integer not null,cost numeric(14,4),kind text not null check(kind in ('delivery','reversal','restock','correction')),created_at timestamptz not null default now(),created_by uuid default auth.uid(),foreign key(workspace_id,product_id) references public.inventory(workspace_id,id));
-- Remove Supabase default table privileges before granting the exact API surface.
revoke all on public.workspaces,public.profiles,public.workspace_members,public.vendors,public.team_members,public.inventory,public.orders,public.team_payouts,public.inventory_movements from anon,authenticated;
insert into public.profiles(id,email,display_name) select id,coalesce(email,''),coalesce(raw_user_meta_data->>'full_name','') from auth.users on conflict(id) do nothing;
-- Default deny; every granted operation below is explicitly workspace scoped.
alter table public.workspaces enable row level security;
alter table public.profiles enable row level security;
alter table public.workspace_members enable row level security;
create policy read_workspace on public.workspaces for select to authenticated using(private.has_role(id));
create policy read_own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy read_own_membership on public.workspace_members for select to authenticated using(user_id=auth.uid());
grant select on public.workspaces,public.profiles,public.workspace_members to authenticated;
do $$ declare t text;begin foreach t in array array['inventory','orders','vendors','team_members','team_payouts','inventory_movements'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy workspace_read on public.%I for select to authenticated using(private.has_role(workspace_id))',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create index %I on public.%I(workspace_id,id)',t||'_workspace_idx',t);
 end loop;end $$;
-- Metadata writes use RLS. Stock, orders, balances and payouts have no direct client write grants.
create policy vendors_insert on public.vendors for insert to authenticated with check(private.has_role(workspace_id,array['admin','manager']));
create policy vendors_update on public.vendors for update to authenticated using(private.has_role(workspace_id,array['admin','manager'])) with check(private.has_role(workspace_id,array['admin','manager']));
create policy vendors_delete on public.vendors for delete to authenticated using(private.has_role(workspace_id,array['admin','manager']));
grant insert(id,workspace_id,name,contact_person,email,phone,website,lead_time_days,rating,notes,created_at),update(name,contact_person,email,phone,website,lead_time_days,rating,notes,created_at) on public.vendors to authenticated;
grant delete on public.vendors to authenticated;
create policy team_insert on public.team_members for insert to authenticated with check(private.has_role(workspace_id,array['admin']));
create policy team_update on public.team_members for update to authenticated using(private.has_role(workspace_id,array['admin'])) with check(private.has_role(workspace_id,array['admin']));
create policy team_delete on public.team_members for delete to authenticated using(private.has_role(workspace_id,array['admin']));
grant insert(id,workspace_id,name,phone,email,base_reward,reward_trigger,reward_calculation_mode,status,notes,created_at),update(name,phone,email,base_reward,reward_trigger,reward_calculation_mode,status,notes,created_at) on public.team_members to authenticated;
grant delete on public.team_members to authenticated;
create function private.refresh_bundles(w uuid) returns void language sql set search_path='' as $$ update public.inventory b set stock=coalesce((select min(p.stock/(part->>'quantity')::integer) from jsonb_array_elements(b.bundle_items) part join public.inventory p on p.id=(part->>'itemId')::uuid and p.workspace_id=w),0),updated_at=now() where b.workspace_id=w and b.is_bundle $$;
create function private.consume(w uuid,pid uuid,qty integer,movement_kind text default 'delivery',source_order uuid default null) returns jsonb language plpgsql set search_path='' as $$
declare p public.inventory;part jsonb;lot jsonb;lots jsonb:='[]';alloc jsonb:='[]';needed integer:=qty;taken integer;begin
 if qty<=0 then raise exception 'Invalid quantity';end if;
 select * into strict p from public.inventory where workspace_id=w and id=pid for update;
 if p.is_bundle then for part in select value from jsonb_array_elements(p.bundle_items) order by value->>'itemId' loop alloc:=alloc||private.consume(w,(part->>'itemId')::uuid,qty*(part->>'quantity')::integer,movement_kind,source_order);end loop;return alloc;end if;
 if p.stock<qty then raise exception 'Not enough stock to deliver % (available %, requested %)',p.title,p.stock,qty;end if;
 if jsonb_array_length(p.batches)=0 then p.batches:=jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'batchNumber',1,'receivedDate',p.created_at::date,'initialQty',p.stock,'remainingQty',p.stock,'costPrice',p.cost_price,'sellingPrice',p.selling_price,'createdAt',p.created_at));end if;
 for lot in select value from jsonb_array_elements(p.batches) order by coalesce((value->>'batchNumber')::integer,0),value->>'receivedDate' loop
 taken:=least(needed,coalesce((lot->>'remainingQty')::integer,0));if taken>0 then alloc:=alloc||jsonb_build_array(jsonb_build_object('productId',pid,'batchId',lot->>'id','quantity',taken,'costPrice',(lot->>'costPrice')::numeric));lot:=jsonb_set(lot,'{remainingQty}',to_jsonb((lot->>'remainingQty')::integer-taken));needed:=needed-taken;end if;lots:=lots||jsonb_build_array(lot);
 end loop;
 if needed>0 then raise exception 'Stock batches do not reconcile for %',p.title;end if;
 update public.inventory set batches=lots,stock=stock-qty,cost_price=coalesce((select (l->>'costPrice')::numeric from jsonb_array_elements(lots) l where (l->>'remainingQty')::integer>0 limit 1),cost_price),status=case when stock-qty=0 then 'out_of_stock' else status end,updated_at=now() where id=pid;
 insert into public.inventory_movements(workspace_id,product_id,quantity,cost,kind,order_id) values(w,pid,-qty,(select sum((a->>'quantity')::numeric*(a->>'costPrice')::numeric)/qty from jsonb_array_elements(alloc) a),movement_kind,source_order);return alloc;
end $$;
create function private.restore(w uuid,alloc jsonb) returns void language plpgsql set search_path='' as $$ declare a jsonb;p public.inventory;lots jsonb;begin
 for a in select value from jsonb_array_elements(alloc) order by value->>'productId' loop
 select * into strict p from public.inventory where workspace_id=w and id=(a->>'productId')::uuid for update;
 if not exists(select 1 from jsonb_array_elements(p.batches) l where l->>'id'=a->>'batchId') then raise exception 'Original stock batch is missing';end if;
 select jsonb_agg(case when l->>'id'=a->>'batchId' then jsonb_set(l,'{remainingQty}',to_jsonb((l->>'remainingQty')::integer+(a->>'quantity')::integer)) else l end order by ord) into lots from jsonb_array_elements(p.batches) with ordinality as x(l,ord);
 update public.inventory set batches=lots,stock=stock+(a->>'quantity')::integer,cost_price=coalesce((select (l->>'costPrice')::numeric from jsonb_array_elements(lots) l where (l->>'remainingQty')::integer>0 limit 1),cost_price),status=case when status='archived' then status else 'active' end,updated_at=now() where id=p.id;
 insert into public.inventory_movements(workspace_id,product_id,quantity,cost,kind) values(w,p.id,(a->>'quantity')::integer,(a->>'costPrice')::numeric,'reversal');
 end loop;end $$;
create function private.save_order(target_workspace uuid,order_id uuid,order_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare previous public.orders;n public.orders;p public.inventory;m public.team_members;is_update boolean;terms_changed boolean;eligible boolean;cost numeric;begin
 perform private.require_role(target_workspace,array['admin','manager','staff']);
 select * into previous from public.orders where id=order_id for update;is_update:=found;if is_update and previous.workspace_id<>target_workspace then raise exception 'Order not found';end if;
 n:=jsonb_populate_record(null::public.orders,order_data);n.id:=order_id;n.workspace_id:=target_workspace;n.created_at:=case when is_update then previous.created_at else now() end;n.created_by:=case when is_update then previous.created_by else auth.uid() end;
 n.date:=coalesce(case when is_update then previous.date else n.date end,(now() at time zone 'Africa/Casablanca')::date);n.status:=coalesce(n.status,'new');n.quantity:=coalesce(n.quantity,1);n.unit_cost:=coalesce(n.unit_cost,0);n.shipping_charged:=coalesce(n.shipping_charged,0);n.shipping_cost:=coalesce(n.shipping_cost,0);n.platform_fee:=coalesce(n.platform_fee,0);n.buyer_name:=coalesce(n.buyer_name,'');n.payment_method:=coalesce(n.payment_method,'cash');n.fulfillment_type:=coalesce(n.fulfillment_type,'local_pickup');n.stock_allocations:='[]';
 if n.quantity<=0 or n.sale_price is null or n.sale_price<0 then raise exception 'Invalid quantity or price';end if;
 terms_changed:=not is_update or n.item_id is distinct from previous.item_id or n.quantity<>previous.quantity or (n.status in ('delivered','completed')) is distinct from (previous.status in ('delivered','completed'));
 if is_update and terms_changed and previous.status in ('delivered','completed') then perform private.restore(target_workspace,previous.stock_allocations);end if;
 if n.item_id is not null then select * into strict p from public.inventory where workspace_id=target_workspace and id=n.item_id; if p.status='archived' and (not is_update or n.item_id is distinct from previous.item_id) then raise exception 'Product is archived';end if;n.item_title:=p.title;n.base_price:=p.selling_price;n.unit_cost:=p.cost_price;else n.base_price:=coalesce(n.sale_price,0);end if;
 if n.status in ('delivered','completed') then
 if not terms_changed then n.stock_allocations:=previous.stock_allocations;n.unit_cost:=previous.unit_cost;elsif n.item_id is not null then n.stock_allocations:=private.consume(target_workspace,n.item_id,n.quantity,'delivery',order_id);select sum((a->>'quantity')::numeric*(a->>'costPrice')::numeric)/n.quantity into cost from jsonb_array_elements(n.stock_allocations) a;n.unit_cost:=cost;end if;
 n.delivered_date:=coalesce(case when is_update and previous.status in ('delivered','completed') then previous.delivered_date end,n.delivered_date,(now() at time zone 'Africa/Casablanca')::date);
 else n.delivered_date:=null;end if;
 n.member_reward:=0;n.reward_status:=case when n.status='cancelled' then 'cancelled' else 'pending' end;
 if n.confirmation_member_id is not null then
 select * into strict m from public.team_members where workspace_id=target_workspace and id=n.confirmation_member_id;n.confirmation_member_name:=m.name;n.reward_trigger:=m.reward_trigger;n.reward_calculation_mode:=m.reward_calculation_mode;
 eligible:=n.status in ('delivered','completed') or (m.reward_trigger='confirmed' and n.status in ('confirmed','pending_pickup','shipped'));
 if eligible then n.reward_status:='granted';
 if is_update and previous.reward_status='granted' and previous.confirmation_member_id=n.confirmation_member_id and previous.quantity=n.quantity and previous.sale_price=n.sale_price and previous.item_id is not distinct from n.item_id then n.member_reward:=previous.member_reward;n.base_price:=previous.base_price;
 else n.member_reward:=round(m.base_reward*case when m.reward_calculation_mode='per_item' then n.quantity else 1 end+greatest(n.sale_price-n.base_price,0)*n.quantity,2);end if;end if;
 end if;
 n.total_revenue:=round(n.sale_price*n.quantity+n.shipping_charged,2);n.total_cost:=round(n.unit_cost*n.quantity+n.shipping_cost+n.platform_fee,2);n.net_profit:=case when n.status='cancelled' then 0 else n.total_revenue-n.total_cost-n.member_reward end;n.profit_margin:=case when n.total_revenue>0 then round(n.net_profit*100/n.total_revenue,2) else 0 end;
 insert into public.orders select n.* on conflict(id) do update set workspace_id=excluded.workspace_id,item_id=excluded.item_id,item_title=excluded.item_title,quantity=excluded.quantity,unit_cost=excluded.unit_cost,sale_price=excluded.sale_price,shipping_charged=excluded.shipping_charged,shipping_cost=excluded.shipping_cost,platform_fee=excluded.platform_fee,total_revenue=excluded.total_revenue,total_cost=excluded.total_cost,net_profit=excluded.net_profit,profit_margin=excluded.profit_margin,buyer_name=excluded.buyer_name,customer_phone=excluded.customer_phone,customer_address=excluded.customer_address,google_maps_url=excluded.google_maps_url,payment_method=excluded.payment_method,fulfillment_type=excluded.fulfillment_type,carrier=excluded.carrier,tracking_number=excluded.tracking_number,status=excluded.status,date=excluded.date,delivered_date=excluded.delivered_date,notes=excluded.notes,created_at=excluded.created_at,created_by=excluded.created_by,confirmation_member_id=excluded.confirmation_member_id,confirmation_member_name=excluded.confirmation_member_name,base_price=excluded.base_price,member_reward=excluded.member_reward,reward_trigger=excluded.reward_trigger,reward_status=excluded.reward_status,reward_calculation_mode=excluded.reward_calculation_mode,stock_allocations=excluded.stock_allocations;
 perform private.refresh_bundles(target_workspace);return order_id;
end $$;
create function public.save_order(target_workspace uuid,order_id uuid,order_data jsonb) returns uuid language sql security invoker set search_path='' as $$ select private.save_order(target_workspace,order_id,order_data) $$;
create function private.delete_order(target_workspace uuid,order_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare o public.orders;begin perform private.require_role(target_workspace,array['admin','manager']);select * into strict o from public.orders where workspace_id=target_workspace and id=order_id for update;if o.status in ('delivered','completed') then perform private.restore(target_workspace,o.stock_allocations);end if;delete from public.orders where workspace_id=target_workspace and id=order_id;perform private.refresh_bundles(target_workspace);end $$;
create function public.delete_order(target_workspace uuid,order_id uuid) returns void language sql security invoker set search_path='' as $$ select private.delete_order(target_workspace,order_id) $$;
create function private.import_orders(target_workspace uuid,order_rows jsonb) returns integer language plpgsql security definer set search_path='' as $$ declare r jsonb;n integer:=0;begin perform private.require_role(target_workspace,array['admin','manager']);if jsonb_array_length(order_rows)>500 then raise exception 'Import at most 500 orders per transaction';end if;for r in select value from jsonb_array_elements(order_rows) loop if r->>'status' in ('delivered','completed') and not (r ? 'delivered_date') then r:=r||jsonb_build_object('delivered_date',r->>'date');end if;perform private.save_order(target_workspace,gen_random_uuid(),r);n:=n+1;end loop;return n;end $$;
create function public.import_orders(target_workspace uuid,order_rows jsonb) returns integer language sql security invoker set search_path='' as $$ select private.import_orders(target_workspace,order_rows) $$;

create function private.save_inventory(target_workspace uuid,product_id uuid,product jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare p public.inventory;old public.inventory;part jsonb;exists_before boolean;begin
 perform private.require_role(target_workspace,array['admin','manager','staff']);
 select * into old from public.inventory where id=product_id for update;exists_before:=found;if exists_before and old.workspace_id<>target_workspace then raise exception 'Product not found';end if;
 p:=jsonb_populate_record(null::public.inventory,coalesce(to_jsonb(old),'{}')||product);p.id:=product_id;p.workspace_id:=target_workspace;p.title:=trim(p.title);p.category:=coalesce(p.category,'Other');p.condition:=coalesce(p.condition,'new');p.cost_price:=coalesce(p.cost_price,0);p.selling_price:=coalesce(p.selling_price,0);p.stock:=coalesce(p.stock,0);p.low_stock_threshold:=coalesce(p.low_stock_threshold,2);p.status:=coalesce(p.status,'active');p.fulfillment_type:=coalesce(p.fulfillment_type,'both');p.is_bundle:=coalesce(p.is_bundle,false);p.bundle_items:=coalesce(p.bundle_items,'[]');p.batches:=coalesce(p.batches,'[]');p.created_at:=case when exists_before then old.created_at else now() end;p.updated_at:=now();p.created_by:=case when exists_before then old.created_by else auth.uid() end;
 if exists_before then if p.is_bundle<>old.is_bundle then raise exception 'Cannot change product kind';end if;if not p.is_bundle and p.stock<>old.stock then raise exception 'Use restock or stock adjustment to change existing stock';end if;p.batches:=old.batches;end if;
 if p.is_bundle then
 if jsonb_array_length(p.bundle_items)=0 then raise exception 'Add bundle components';end if;
 for part in select value from jsonb_array_elements(p.bundle_items) loop
 if coalesce((part->>'quantity')::integer,0)<=0 or not exists(select 1 from public.inventory where workspace_id=target_workspace and id=(part->>'itemId')::uuid and not is_bundle and status<>'archived') then raise exception 'Invalid bundle component';end if;end loop;
 p.stock:=0;p.batches:='[]';
 elsif not exists_before then p.batches:=case when p.stock>0 then jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'batchNumber',1,'receivedDate',(now() at time zone 'Africa/Casablanca')::date,'initialQty',p.stock,'remainingQty',p.stock,'costPrice',p.cost_price,'sellingPrice',p.selling_price,'createdAt',now())) else '[]' end;end if;
 insert into public.inventory select p.* on conflict(id) do update set title=excluded.title,sku=excluded.sku,category=excluded.category,condition=excluded.condition,cost_price=excluded.cost_price,selling_price=excluded.selling_price,low_stock_threshold=excluded.low_stock_threshold,vendor_id=excluded.vendor_id,vendor_name=excluded.vendor_name,listing_url=excluded.listing_url,status=excluded.status,fulfillment_type=excluded.fulfillment_type,notes=excluded.notes,bundle_items=excluded.bundle_items,updated_at=excluded.updated_at;
 perform private.refresh_bundles(target_workspace);return product_id;end $$;
create function public.save_inventory(target_workspace uuid,product_id uuid,product jsonb) returns uuid language sql security invoker set search_path='' as $$ select private.save_inventory(target_workspace,product_id,product) $$;
create function private.restock_inventory(target_workspace uuid,product_id uuid,lot jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.inventory;q integer;cost numeric;price numeric;begin
 perform private.require_role(target_workspace,array['admin','manager','staff']);select * into strict p from public.inventory where workspace_id=target_workspace and id=product_id for update;
 if p.is_bundle then raise exception 'Restock bundle components instead';end if;
 q:=(lot->>'quantity')::integer;cost:=(lot->>'cost_price')::numeric;price:=(lot->>'selling_price')::numeric;if q is null or q<=0 or cost is null or cost<0 or price is null or price<0 then raise exception 'Invalid restock';end if;
 p.batches:=p.batches||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'batchNumber',jsonb_array_length(p.batches)+1,'receivedDate',coalesce((lot->>'received_date')::date,(now() at time zone 'Africa/Casablanca')::date),'initialQty',q,'remainingQty',q,'costPrice',cost,'sellingPrice',price,'supplier',lot->>'supplier','notes',lot->>'notes','createdAt',now()));
 update public.inventory set batches=p.batches,stock=stock+q,cost_price=case when stock=0 then cost else cost_price end,selling_price=case when stock=0 then price else selling_price end,status=case when status='archived' then status else 'active' end,updated_at=now() where id=product_id returning * into p;
 insert into public.inventory_movements(workspace_id,product_id,quantity,cost,kind) values(target_workspace,product_id,q,cost,'restock');perform private.refresh_bundles(target_workspace);return to_jsonb(p);end $$;
create function public.restock_inventory(target_workspace uuid,product_id uuid,lot jsonb) returns jsonb language sql security invoker set search_path='' as $$ select private.restock_inventory(target_workspace,product_id,lot) $$;
create function private.adjust_stock(target_workspace uuid,product_id uuid,delta integer) returns void language plpgsql security definer set search_path='' as $$ declare p public.inventory;begin perform private.require_role(target_workspace,array['admin','manager']);if delta=0 then return;end if;select * into strict p from public.inventory where workspace_id=target_workspace and id=product_id for update;if delta>0 then perform private.restock_inventory(target_workspace,product_id,jsonb_build_object('quantity',delta,'cost_price',p.cost_price,'selling_price',p.selling_price,'notes','Stock correction'));else perform private.consume(target_workspace,product_id,-delta,'correction');end if;perform private.refresh_bundles(target_workspace);end $$;
create function public.adjust_stock(target_workspace uuid,product_id uuid,delta integer) returns void language sql security invoker set search_path='' as $$ select private.adjust_stock(target_workspace,product_id,delta) $$;
create function private.archive_inventory(target_workspace uuid,product_id uuid,archive boolean) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_role(target_workspace,array['admin','manager','staff']);update public.inventory set status=case when archive then 'archived' when stock>0 then 'active' else 'out_of_stock' end,updated_at=now() where workspace_id=target_workspace and id=product_id;if not found then raise exception 'Product not found';end if;end $$;
create function public.archive_inventory(target_workspace uuid,product_id uuid,archive boolean) returns void language sql security invoker set search_path='' as $$ select private.archive_inventory(target_workspace,product_id,archive) $$;
create function private.delete_inventory(target_workspace uuid,product_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_role(target_workspace,array['admin','manager']);if exists(select 1 from public.orders where workspace_id=target_workspace and item_id=product_id) or exists(select 1 from public.inventory b,jsonb_array_elements(b.bundle_items) part where b.workspace_id=target_workspace and part->>'itemId'=product_id::text) then raise exception 'This product has history or belongs to a bundle. Archive it instead.';end if;delete from public.inventory_movements where workspace_id=target_workspace and public.inventory_movements.product_id=delete_inventory.product_id;delete from public.inventory where workspace_id=target_workspace and id=product_id;end $$;
create function public.delete_inventory(target_workspace uuid,product_id uuid) returns void language sql security invoker set search_path='' as $$ select private.delete_inventory(target_workspace,product_id) $$;
create function private.record_payout(target_workspace uuid,payout_id uuid,payout jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare n public.team_payouts;old public.team_payouts;m public.team_members;earned numeric;paid numeric;begin
 perform private.require_role(target_workspace,array['admin','manager']);n:=jsonb_populate_record(null::public.team_payouts,payout);
 select * into old from public.team_payouts where id=payout_id;if found then if old.workspace_id=target_workspace and old.member_id=n.member_id and old.amount=n.amount then return payout_id;else raise exception 'Payout request conflicts with existing record';end if;end if;
 select * into strict m from public.team_members where workspace_id=target_workspace and id=n.member_id for update;
 select coalesce(sum(member_reward),0) into earned from public.orders where workspace_id=target_workspace and confirmation_member_id=m.id and reward_status='granted' and status<>'cancelled';select coalesce(sum(amount),0) into paid from public.team_payouts where workspace_id=target_workspace and member_id=m.id;
 if n.amount is null or n.amount<=0 or n.amount>earned-paid then raise exception 'Payout exceeds earned unpaid rewards';end if;
 n.id:=payout_id;n.workspace_id:=target_workspace;n.member_name:=m.name;n.date:=coalesce(n.date,(now() at time zone 'Africa/Casablanca')::date);n.created_at:=now();n.created_by:=auth.uid();n.payment_method:=coalesce(n.payment_method,'cash');insert into public.team_payouts select n.*;update public.team_members set total_paid=paid+n.amount where id=m.id;return payout_id;end $$;
create function public.record_payout(target_workspace uuid,payout_id uuid,payout jsonb) returns uuid language sql security invoker set search_path='' as $$ select private.record_payout(target_workspace,payout_id,payout) $$;
create function private.delete_payout(target_workspace uuid,payout_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare p public.team_payouts;begin perform private.require_role(target_workspace,array['admin','manager']);delete from public.team_payouts where workspace_id=target_workspace and id=payout_id returning * into p;if not found then raise exception 'Payout not found';end if;update public.team_members set total_paid=(select coalesce(sum(amount),0) from public.team_payouts where workspace_id=target_workspace and member_id=p.member_id) where id=p.member_id;end $$;
create function public.delete_payout(target_workspace uuid,payout_id uuid) returns void language sql security invoker set search_path='' as $$ select private.delete_payout(target_workspace,payout_id) $$;
create function private.set_member_role(target_workspace uuid,target_user uuid,new_role text) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_role(target_workspace,array['admin']);if new_role not in ('admin','manager','staff','viewer') or new_role is null then raise exception 'Invalid role';end if;if new_role<>'admin' and exists(select 1 from public.workspace_members where workspace_id=target_workspace and user_id=target_user and role='admin') and (select count(*) from public.workspace_members where workspace_id=target_workspace and role='admin')<=1 then raise exception 'Keep at least one workspace admin';end if;update public.workspace_members set role=new_role where workspace_id=target_workspace and user_id=target_user;if not found then raise exception 'Workspace member not found';end if;end $$;
create function public.set_member_role(target_workspace uuid,target_user uuid,new_role text) returns void language sql security invoker set search_path='' as $$ select private.set_member_role(target_workspace,target_user,new_role) $$;
create function private.list_workspace_members(target_workspace uuid) returns jsonb language plpgsql security definer set search_path='' as $$ begin perform private.require_role(target_workspace,array['admin']);return (select coalesce(jsonb_agg(jsonb_build_object('uid',m.user_id,'role',m.role,'email',p.email,'displayName',p.display_name)),'[]') from public.workspace_members m join public.profiles p on p.id=m.user_id where m.workspace_id=target_workspace);end $$;
create function public.list_workspace_members(target_workspace uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.list_workspace_members(target_workspace) $$;
-- No public/anonymous function execution. Only audited entry points are callable.
do $$ declare r record;begin for r in select p.oid::regprocedure signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('save_order','delete_order','import_orders','save_inventory','restock_inventory','adjust_stock','archive_inventory','delete_inventory','record_payout','delete_payout','set_member_role','list_workspace_members','consume','restore','refresh_bundles') loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);if r.proname not in ('consume','restore','refresh_bundles') then execute format('grant execute on function %s to authenticated',r.signature);end if;end loop;end $$;
-- Realtime in Supabase; omitted safely in an embedded PostgreSQL test instance.
do $$ declare t text;begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then foreach t in array array['inventory','orders','vendors','team_members','team_payouts'] loop execute format('alter publication supabase_realtime add table public.%I',t);end loop;end if;end $$;

do $$ declare t text;begin foreach t in array array['inventory','orders','team_members','team_payouts','vendors','inventory_movements'] loop execute format('drop policy workspace_read on public.%I',t);execute format('create policy workspace_read on public.%I for select to authenticated using(private.has_role(workspace_id,array[''admin'',''manager'']))',t);end loop;end $$;
create function private.read_workspace_records(target_workspace uuid,table_name text,page_offset integer default 0,page_size integer default 500,entity_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare records jsonb;total bigint;financial boolean;begin
 if not private.has_role(target_workspace) then raise exception 'Approved workspace access required' using errcode='42501';end if;
 if table_name not in ('inventory','orders','vendors','team_members','team_payouts') or page_offset<0 or page_size<1 or page_size>500 then raise exception 'Invalid read request';end if;
 financial:=private.has_role(target_workspace,array['admin','manager']);
 if not financial and table_name in ('vendors','team_payouts') then return jsonb_build_object('rows','[]'::jsonb,'total',0);end if;
 execute format('select count(*) from public.%I where workspace_id=$1 and ($2 is null or id=$2)',table_name) into total using target_workspace,entity_id;
 execute format('select coalesce(jsonb_agg(to_jsonb(r)),''[]''::jsonb) from (select * from public.%I where workspace_id=$1 and ($2 is null or id=$2) order by id limit $3 offset $4) r',table_name) into records using target_workspace,entity_id,page_size,page_offset;
 if not financial then
 if table_name='inventory' then select coalesce(jsonb_agg(r||jsonb_build_object('cost_price',0,'batches','[]'::jsonb,'bundle_items','[]'::jsonb)),'[]'::jsonb) into records from jsonb_array_elements(records) r;
 elsif table_name='orders' then select coalesce(jsonb_agg(r||jsonb_build_object('unit_cost',0,'total_cost',0,'net_profit',0,'profit_margin',0,'member_reward',0,'base_price',0,'stock_allocations','[]'::jsonb)),'[]'::jsonb) into records from jsonb_array_elements(records) r;
 elsif table_name='team_members' then select coalesce(jsonb_agg(r||jsonb_build_object('base_reward',0,'total_paid',0)),'[]'::jsonb) into records from jsonb_array_elements(records) r;end if;end if;
 return jsonb_build_object('rows',records,'total',total);end $$;
create function public.read_workspace_records(target_workspace uuid,table_name text,page_offset integer default 0,page_size integer default 500,entity_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$ select private.read_workspace_records(target_workspace,table_name,page_offset,page_size,entity_id) $$;
revoke all on function public.read_workspace_records(uuid,text,integer,integer,uuid),private.read_workspace_records(uuid,text,integer,integer,uuid) from public,anon;
grant execute on function public.read_workspace_records(uuid,text,integer,integer,uuid),private.read_workspace_records(uuid,text,integer,integer,uuid) to authenticated;

-- Reject NaN money explicitly (PostgreSQL considers NaN greater than finite numbers).
do $$ declare c record;begin for c in select table_name,column_name from information_schema.columns where table_schema='public' and table_name in ('inventory','orders','team_members','team_payouts','inventory_movements','vendors') and data_type='numeric' loop execute format('alter table public.%I add constraint %I check(%I <> ''NaN''::numeric)',c.table_name,c.table_name||'_'||c.column_name||'_finite',c.column_name);end loop;end $$;
create function private.refresh_employee_rewards() returns trigger language plpgsql set search_path='' as $$ declare o public.orders;begin if new.reward_trigger is distinct from old.reward_trigger then for o in select * from public.orders where workspace_id=new.workspace_id and confirmation_member_id=new.id and status not in ('delivered','completed') loop perform private.save_order(new.workspace_id,o.id,to_jsonb(o));end loop;end if;return new;end $$;
revoke all on function private.refresh_employee_rewards() from public,anon,authenticated;
create trigger refresh_employee_rewards after update of reward_trigger on public.team_members for each row execute function private.refresh_employee_rewards();
